SELECT c.* FROM courses c LEFT JOIN schedules s ON c.id = s.course_id WHERE 1=1
AND (c.course_name LIKE CONCAT('%', #{search}, '%') OR c.description LIKE CONCAT('%', #{search}, '%'))
AND c.credits = #{credits}
AND s.day_of_week = #{weekday}
GROUP BY c.id

SELECT COUNT(DISTINCT c.id) FROM courses c LEFT JOIN schedules s ON c.id = s.course_id WHERE 1=1
AND (c.course_name LIKE CONCAT('%', #{search}, '%') OR c.description LIKE CONCAT('%', #{search}, '%'))
AND c.credits = #{credits}
AND s.day_of_week = #{weekday}
